preConditionHook:
// An ioi completed one bar ago: inside bar at [3], outside bar at [2],
// inside bar at [1]. Containment and engulfing are both inclusive, matching
// InsideBarInclusive.
ioi = el_le(high[3], high[4]) && el_ge(low[3], low[4])
      && el_ge(high[2], high[3]) && el_le(low[2], low[3])
      && el_le(high[1], high[2]) && el_ge(low[1], low[2]);
// The two disqualifiers, kept in the hook because EL does NOT short-circuit
// (EL_FEATURES.md) and the deep subscripts above are reached on every bar
// regardless: Max Bars Back must cover index 4 unconditionally.
tooBig = el_ge(high[1] - low[1], maxInsideFraction * (high[2] - low[2]));
nearCentre = el_le(std::fabs((high[1] + low[1]) / 2 - (high[2] + low[2]) / 2),
                   centreBand * (high[2] - low[2]));
